import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// A naive 3D transposed convolution kernel (for demonstration purposes).
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int in_depth,
    int in_height,
    int in_width,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool has_bias,
    const float* __restrict__ bias,
    int out_depth,
    int out_height,
    int out_width
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elems = batch_size * out_channels * out_depth * out_height * out_width;
    if (idx >= total_elems) {
        return;
    }

    int ow = idx % out_width;
    int oh = (idx / out_width) % out_height;
    int od = (idx / (out_width * out_height)) % out_depth;
    int oc = (idx / (out_width * out_height * out_depth)) % out_channels;
    int n  = idx / (out_width * out_height * out_depth * out_channels);

    float val = 0.0f;
    for (int ic = 0; ic < in_channels; ic++) {
        for (int kd = 0; kd < kernel_size; kd++) {
            for (int kh = 0; kh < kernel_size; kh++) {
                for (int kw = 0; kw < kernel_size; kw++) {
                    int id = od + padding - kd * dilation;
                    int ih = oh + padding - kh * dilation;
                    int iw = ow + padding - kw * dilation;
                    if ((id % stride == 0) && (ih % stride == 0) && (iw % stride == 0)) {
                        id /= stride;
                        ih /= stride;
                        iw /= stride;
                        if ((id >= 0) && (id < in_depth) &&
                            (ih >= 0) && (ih < in_height) &&
                            (iw >= 0) && (iw < in_width)) {
                            int input_idx = n * in_channels * in_depth * in_height * in_width
                                          + ic * in_depth * in_height * in_width
                                          + id * in_height * in_width
                                          + ih * in_width
                                          + iw;
                            int weight_idx = oc * in_channels * kernel_size * kernel_size * kernel_size
                                           + ic * kernel_size * kernel_size * kernel_size
                                           + kd * kernel_size * kernel_size
                                           + kh * kernel_size
                                           + kw;
                            val += input[input_idx] * weight[weight_idx];
                        }
                    }
                }
            }
        }
    }
    if (has_bias) {
        val += bias[oc];
    }
    output[idx] = val;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_depth = input.size(2);
    auto in_height = input.size(3);
    auto in_width = input.size(4);

    auto out_channels = weight.size(0);
    auto kernel_size = weight.size(2);  // assuming [out_c, in_c, K, K, K]
    bool has_bias = (bias.defined() && bias.numel() > 0);

    // Compute the output dimensions for conv transpose:
    // out_dim = (in_dim - 1)*stride - 2*pad + dilation*(kernel_size - 1) + 1
    int out_depth = (in_depth - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;
    int out_height = (in_height - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;
    int out_width = (in_width - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;

    auto opts = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({batch_size, out_channels, out_depth, out_height, out_width}, opts);

    int total_elems = batch_size * out_channels * out_depth * out_height * out_width;
    const int block_size = 256;
    int grid_size = (total_elems + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        in_depth,
        in_height,
        in_width,
        out_channels,
        kernel_size,
        stride,
        padding,
        dilation,
        has_bias,
        has_bias ? bias.data_ptr<float>() : nullptr,
        out_depth,
        out_height,
        out_width
    );

    return output;
}
""";

conv_transpose3d_cpp_source = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation
);
""";

conv_transpose3d = load_inline(
    name="conv_transpose3d_extension",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    A custom 3D transposed convolution module using a naive CUDA kernel for demonstration.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride=1, padding=0, dilation=1, bias=False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.use_bias = bias

        # Initialize weights similarly to nn.ConvTranspose3d
        self.weight = nn.Parameter(
            torch.randn(out_channels, in_channels, kernel_size, kernel_size, kernel_size)
        )
        if self.use_bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose3d.conv_transpose3d_cuda(
            x,
            self.weight,
            self.bias if self.use_bias else torch.tensor([], device=x.device, dtype=x.dtype),
            self.stride,
            self.padding,
            self.dilation
        )
